import{_ as o,c as l,b as n,d as i,a as e,e as s,w as m,r as p,o as r}from"./app-CJkd1fBW.js";const c="/images/Development_Manual/current/module-architecture.svg",h="/images/Development_Manual/current/frame-lifecycle.svg",d="/images/Development_Manual/current/plugin-lifecycle.svg",g="/images/Development_Manual/Code_Structure_01.png",u="/images/Development_Manual/Code_Structure_02.png",w="/images/Development_Manual/Code_Structure_03.png",x="/images/Development_Manual/Code_Structure_04.png",y="/images/Development_Manual/Code_Structure_05.png",f="/images/Development_Manual/Code_Structure_06.png",v={};function k(b,a){const t=p("VPLink");return r(),l("div",null,[n("p",null,[e(t,{href:"./Documentation.md"},{default:m(()=>[...a[0]||(a[0]=[s("Documentation",-1)])]),_:1}),a[3]||(a[3]=s(" · ",-1)),e(t,{href:"./Build_Crystal_Project.md"},{default:m(()=>[...a[1]||(a[1]=[s("Build Crystal Project",-1)])]),_:1}),a[4]||(a[4]=s(" · ",-1)),e(t,{href:"./Volumes_and_Scenes.md"},{default:m(()=>[...a[2]||(a[2]=[s("Volumes and Scenes",-1)])]),_:1})]),a[13]||(a[13]=i('<h2 id="module-architecture" tabindex="-1"><a class="header-anchor" href="#module-architecture"><span>Module architecture</span></a></h2><p><img src="'+c+'" alt="Crystal module architecture with GUI, CLI and Python entry points, application and plugin boundaries, and the shared C++/CUDA engine."></p><p><em>Figure 1. Execution routes and ownership at the module level. The graph shows the interactive viewport, public renderer and plugin job paths. The desktop architecture Help separately shows generated include dependencies.</em></p><table><thead><tr><th>Source location</th><th>Owns</th><th>Read it when…</th></tr></thead><tbody><tr><td><code>src/CrystalGUI</code></td><td>Home window, Qt workspaces, rendering worker and viewport, volume and mapping editors</td><td>Adding interaction, a visual control or display behavior</td></tr><tr><td><code>src/CrystalCmd</code> and <code>src/PystalBinding</code></td><td>CLI entry points and Python argument/array adaptation</td><td>Exposing a repeatable render workflow</td></tr><tr><td><code>src/CrystalCore</code></td><td>Public <code>Renderer</code>, <code>SceneCodec</code>, volume services and <code>RenderJob</code></td><td>Loading/saving scenes, implementing a host service or dispatching a render job</td></tr><tr><td><code>src/CrystalPlugins</code></td><td>Versioned C ABI, plugin host and renderer adaptation</td><td>Extending a native plugin or checking compatibility</td></tr><tr><td><code>src/CrystalAlgorithm/Scene</code>, <code>Camera</code>, <code>Light</code>, <code>Material</code>, <code>Shape</code></td><td>Scene aggregation, camera/Film, optical inputs and geometry</td><td>Tracing camera or world coordinates, lights, shapes and materials</td></tr><tr><td><code>src/CrystalAlgorithm/Visualizer</code></td><td>Renderer selection and integration algorithms</td><td>Changing renderer behavior or supported combinations</td></tr><tr><td><code>src/CrystalAlgorithm/Volume</code> and <code>Utility</code></td><td>Typed grids, asset I/O, memory and sampling, CUDA views and acceleration</td><td>Changing layout, decoding, transforms, allocation or sampling</td></tr><tr><td><code>src/CrystalAlgorithm/DataMapper</code></td><td>Channel and document mapping, validation and runtime lookup data</td><td>Changing how samples become materials</td></tr><tr><td><code>src/CrystalAlgorithm/Preprocess</code>, <code>Postprocess</code>, <code>DeepLearning</code></td><td>Data preparation, output processing and data generation</td><td>Tracing derived data or Gaussian project export</td></tr><tr><td><code>Support/PyScripts</code>, <code>Support/GS3D</code>, <code>Support/Tests</code></td><td>Offline utilities, local Gaussian training and regression entry points</td><td>Reproducing a conversion, postprocessing job or test</td></tr></tbody></table><p><code>scene_crystal</code> assembles the ordinary scene around the selected renderer. <code>largescale</code> handles the large-scale scene family. Renderer IDs and scene family names serve different purposes. Use <code>CrystalCmd --list-renderers</code> to check which renderers your build actually implements.</p><h2 id="runtime-lifecycle" tabindex="-1"><a class="header-anchor" href="#runtime-lifecycle"><span>Runtime lifecycle</span></a></h2><p><img src="'+h+'" alt="Frame workflow from scene configuration and data preparation through CUDA views, renderer execution, Film and output."></p><p><em>Figure 2. Scene assets and current settings produce a consistent render state. The renderer samples borrowed views and writes Film. Output and GUI presentation consume that result.</em></p><ol><li><strong>Decode and resolve.</strong> <code>SceneCodec</code> reads XML/JSON where applicable. The loading plan resolves paths, checks shared source dimensions and derives the ProcessedGrid.</li><li><strong>Prepare host-owned resources.</strong> Volume objects own buffers, arrays and texture handles. DataMapper owns compiled lookup buffers and bounds. Device structs borrow only the views they need.</li><li><strong>Publish at a frame boundary.</strong> A complete valid candidate replaces the active state at a render-safe point. A failed preparation keeps previously committed resources. Volume, camera, lights and mapping revisions determine whether cached acceleration and Film accumulation are reusable.</li><li><strong>Render and present.</strong> The registry and Visualizer select the algorithm. Film accumulates results. The desktop display reads the current frame and presents it in the viewport. CLI/Python return output to the caller according to their API.</li></ol><p>For an intensity or mapping issue, trace <strong>source sample → stored window → normalized value → compiled mapping → optical properties → renderer</strong>. For a geometry issue, trace <strong>SourceGrid → shared transform → ProcessedGrid → volume/world/camera transforms</strong>. These are separate axes of diagnosis.</p><h2 id="render-plugin-lifecycle" tabindex="-1"><a class="header-anchor" href="#render-plugin-lifecycle"><span>Render plugin lifecycle</span></a></h2><p><img src="'+d+'" alt="Plugin job sequence showing a scene request, exclusive instance, scene opening, repeated frames, RGBA8 copy and cleanup."></p><p><em>Figure 3. One job owns one plugin instance. The dynamic library stays loaded until after its instances are destroyed.</em></p><ul><li>The host validates the versioned C ABI, creates an instance, opens a scene and advances it through render steps. The job checks cancellation and can copy an RGBA8 result.</li><li>The DLL that creates an instance destroys it. C ABI calls return a status and use a caller-owned error buffer. Borrowed image views have an explicit stride and a bounded call lifetime.</li><li>The plugins execute in process and adapt the shared engine. The current render ABI handles scene files and frame output. Interactive camera and mask editing use the desktop scene and application interfaces.</li></ul><h2 id="keep-architecture-and-behavior-in-sync" tabindex="-1"><a class="header-anchor" href="#keep-architecture-and-behavior-in-sync"><span>Keep architecture and behavior in sync</span></a></h2>',15)),n("p",null,[a[6]||(a[6]=s("Update ",-1)),a[7]||(a[7]=n("code",null,"Support/Docs/architecture.json",-1)),a[8]||(a[8]=s(" and the relevant detailed source guide when a module boundary, feature or data contract changes. The desktop Help generator embeds the reference into Crystal at build time. See ",-1)),e(t,{href:"./Build_Crystal_Project.md#run-focused-regressions"},{default:m(()=>[...a[5]||(a[5]=[s("build validation",-1)])]),_:1}),a[9]||(a[9]=s(".",-1))]),a[14]||(a[14]=n("p",null,[s("The website diagrams summarize execution and data ownership. Their editable Graphviz sources are in "),n("code",null,"documentation/diagrams/"),s(" in the website repository. The following reference retains the original coordinate, preset, volume and transfer-function material by Chunxiao Xu, PhD.")],-1)),a[15]||(a[15]=n("h2",{id:"original-technical-reference",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#original-technical-reference"},[n("span",null,"Original technical reference")])],-1)),n("p",null,[a[11]||(a[11]=s("This section documents the earlier implementation. Its Volume-Loader description uses legacy classes and refers to native DICOM loading. For current volume and DICOM behavior, see ",-1)),e(t,{href:"./Volumes_and_Scenes.md"},{default:m(()=>[...a[10]||(a[10]=[s("Volumes and Scenes",-1)])]),_:1}),a[12]||(a[12]=s(".",-1))]),a[16]||(a[16]=i('<h3 id="preset-and-scene" tabindex="-1"><a class="header-anchor" href="#preset-and-scene"><span>Preset and Scene</span></a></h3><p>The rendering system is composed of two main classes: one belonging to the Preset layer and the other to the Scene layer. A Preset class object (with the &#39;Preset&#39; suffix) can be initialized from a preset file (XML or JSON). These initialized Preset objects are then used to instantiate the corresponding Scene objects.</p><h3 id="coordinate-system" tabindex="-1"><a class="header-anchor" href="#coordinate-system"><span>Coordinate System</span></a></h3><h4 id="coordinate-system-world-and-camera-coordinate-system" tabindex="-1"><a class="header-anchor" href="#coordinate-system-world-and-camera-coordinate-system"><span>Coordinate System World and Camera Coordinate System</span></a></h4><p>The world coordinate system follows a <strong>right-handed</strong> convention.</p><p>Initially, the coordinate system followed PBRT, and then Mitsuba. For the convenience of 3D reconstruction, we change the coordinate system. Now The camera coordinate system in Crystal is the same as OpenGL.</p><p>The point cloud output will still be converted to the Colmap coordinate system.</p><h5 id="raster-space-and-screen-space" tabindex="-1"><a class="header-anchor" href="#raster-space-and-screen-space"><span>Raster space and Screen space</span></a></h5><p>In the camera coordinate system, the camera is oriented along the <strong>negative z-axis</strong>, with the up vector aligned with the <strong>positive y-axis</strong> and the right direction corresponding to the <strong>positive x-axis</strong>.</p><img src="'+g+'"><ul><li>Image Coordinate System: For an image with width w and height h (the resolution of the film), the pixel range in the image is <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mn>0</mn><mo separator="true">,</mo><mn>0</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[0,0]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mclose">]</span></span></span></span> to <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mi>w</mi><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mi>h</mi><mo>−</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[w−1,h−1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">h</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>.</li><li>Raster Coordinate System (for imaging film): The range of the raster coordinate system is <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mn>0</mn><mo separator="true">,</mo><mn>0</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[0,0]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mclose">]</span></span></span></span> to <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mi>w</mi><mo separator="true">,</mo><mi>h</mi><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[w,h]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">h</span><span class="mclose">]</span></span></span></span>. A pixel <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mi>i</mi><mo separator="true">,</mo><mi>j</mi><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[i,j]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord mathnormal">i</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.05724em;">j</span><span class="mclose">]</span></span></span></span> in the raster coordinate system corresponds to the range <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mi>i</mi><mo separator="true">,</mo><mi>j</mi><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[i,j]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord mathnormal">i</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.05724em;">j</span><span class="mclose">]</span></span></span></span> to <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mi>i</mi><mo>+</mo><mn>1</mn><mo separator="true">,</mo><mi>j</mi><mo>+</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[i+1,j+1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord mathnormal">i</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.854em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.05724em;">j</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>.</li><li>Screen Coordinate System: The range of the screen coordinate system is <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mi>w</mi><mi mathvariant="normal">/</mi><mi>h</mi><mo separator="true">,</mo><mo>−</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-w/h, -1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mord">/</span><span class="mord mathnormal">h</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">−</span><span class="mord">1</span><span class="mclose">]</span></span></span></span> to <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mi>w</mi><mi mathvariant="normal">/</mi><mi>h</mi><mo separator="true">,</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[w/h,1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mord">/</span><span class="mord mathnormal">h</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>.</li></ul><img src="'+u+`"><p>In the image space, the vertical coordinate has lower values at the top and higher values at the bottom, which is the opposite of the camera&#39;s observation. Similarly, the horizontal coordinate is also reversed. Therefore, the Screen2Raster transformation performs coordinate flipping in both the vertical and horizontal directions.</p><p>The screen in Crystal is the normal NDC space and the same as OpenGL. Namely, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">y</span></span></span></span> and <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>z</mi></mrow><annotation encoding="application/x-tex">z</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.04398em;">z</span></span></span></span> are all in range <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-1,1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>. For Screen2Raster transformation:</p><ul><li>Horizontal coordinate, Transforms the range <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mi>w</mi><mi mathvariant="normal">/</mi><mi>h</mi><mo separator="true">,</mo><mo>−</mo><mi>w</mi><mi mathvariant="normal">/</mi><mi>h</mi><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[w/h,−w/h]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mord">/</span><span class="mord mathnormal">h</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mord">/</span><span class="mord mathnormal">h</span><span class="mclose">]</span></span></span></span> to <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mn>0</mn><mo separator="true">,</mo><mi>w</mi><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[0, w]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mclose">]</span></span></span></span>, where <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>w</mi><mi mathvariant="normal">/</mi><mi>h</mi></mrow><annotation encoding="application/x-tex">w/h</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mord">/</span><span class="mord mathnormal">h</span></span></span></span> maps to <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>, and <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>−</mo><mi>w</mi><mi mathvariant="normal">/</mi><mi>h</mi></mrow><annotation encoding="application/x-tex">-w/h</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mord">/</span><span class="mord mathnormal">h</span></span></span></span> maps to <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>w</mi></mrow><annotation encoding="application/x-tex">w</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span></span></span></span>.</li><li>Vertical coordinate, Transforms the range <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-1, 1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> to <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mi>h</mi><mo separator="true">,</mo><mn>0</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[h,0]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord mathnormal">h</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mclose">]</span></span></span></span>, where <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>−</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">−1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">1</span></span></span></span> maps to <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>h</mi></mrow><annotation encoding="application/x-tex">h</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">h</span></span></span></span> and <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> maps to <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>.</li></ul><p>The near plane in NDC is <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>−</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">-1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">1</span></span></span></span>, and the far plane in NDC is <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>+</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">+1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord">1</span></span></span></span>. The range of <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>z</mi></mrow><annotation encoding="application/x-tex">z</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.04398em;">z</span></span></span></span> is also <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mo>+</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-1,+1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">+</span><span class="mord">1</span><span class="mclose">]</span></span></span></span> in Raster plane.</p><h5 id="some-concept-in-crystal" tabindex="-1"><a class="header-anchor" href="#some-concept-in-crystal"><span>Some concept in Crystal</span></a></h5><p>Now, the coordinate system of Crystal is the same as OpenGL.</p><p>In glm::perspective function, given the aspect, distance of near and far plane (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>f</mi><mo>&gt;</mo><mi>n</mi><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">f &gt; n &gt; 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.10764em;">f</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>), the martix is:</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>[ 2*n/(r-l)   0          (r+l)/(r-l)      0         ]</span></span>
<span class="line"><span>[ 0           2*n/(t-b)  (t+b)/(t-b)      0         ]</span></span>
<span class="line"><span>[ 0           0          -(f+n)/(f-n)  -2*f*n/(f-n) ]</span></span>
<span class="line"><span>[ 0           0          -1               0         ]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>where <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>l</mi></mrow><annotation encoding="application/x-tex">l</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.01968em;">l</span></span></span></span> and <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi></mrow><annotation encoding="application/x-tex">r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">r</span></span></span></span> represent the left and right boundaries of the near plane, respectively. <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>t</mi></mrow><annotation encoding="application/x-tex">t</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> and <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>b</mi></mrow><annotation encoding="application/x-tex">b</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span> represent the up and bottom of the near plane, respectively.</p><p>When <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>l</mi><mo>=</mo><mo>−</mo><mi>r</mi></mrow><annotation encoding="application/x-tex">l = -r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.01968em;">l</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.02778em;">r</span></span></span></span> and <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>b</mi><mo>=</mo><mo>−</mo><mi>t</mi></mrow><annotation encoding="application/x-tex">b = -t</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6984em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord mathnormal">t</span></span></span></span>：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>[ n/r   0     0             0           ]</span></span>
<span class="line"><span>[ 0     n/t   0             0           ]</span></span>
<span class="line"><span>[ 0     0    -(f+n)/(f-n)  -2*f*n/(f-n) ]</span></span>
<span class="line"><span>[ 0     0    -1             0           ]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>or using the FOV version, set <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>t</mi><mi>h</mi><mi>f</mi><mo>=</mo><mi>tan</mi><mo>⁡</mo><mo stretchy="false">(</mo><mn>0.5</mn><mo>⋅</mo><msub><mtext>fov</mtext><mi>y</mi></msub><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">thf = \\tan(0.5\\cdot \\text{fov}_y)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">t</span><span class="mord mathnormal">h</span><span class="mord mathnormal" style="margin-right:0.10764em;">f</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">tan</span><span class="mopen">(</span><span class="mord">0.5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord text"><span class="mord">fov</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.03588em;">y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>, aspect=w/h (set as ap):</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>[ 1/(ap*thf)   0       0            0           ]</span></span>
<span class="line"><span>[ 0          1/thf     0            0           ]</span></span>
<span class="line"><span>[ 0            0     -(f+n)/(f-n)  -2*f*n/(f-n) ]</span></span>
<span class="line"><span>[ 0            0      -1            0           ]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The last line has a negative sign, which means in camera coordinate system, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mi>n</mi><mo separator="true">,</mo><mo>−</mo><mi>f</mi><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-n,-f]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord mathnormal">n</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.10764em;">f</span><span class="mclose">]</span></span></span></span> is map to <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-1, 1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>. Within the visible range (perspective projection cone), <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><mi>y</mi><mo>&gt;</mo><mn>0</mn><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">(x,y&gt;0)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">0</span><span class="mclose">)</span></span></span></span> means they still greater than <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> in NDC.</p><h4 id="volume-coordinate-system" tabindex="-1"><a class="header-anchor" href="#volume-coordinate-system"><span>Volume Coordinate System</span></a></h4><p>The resolution of the three axes of the volumetric data is denoted as [res.x, res.y, res.z], while the voxel dimensions along these axes in world space are represented as [vs.x, vs.y, vs.z]. The resolution and voxel dimensions are multiplied element-wise to obtain the actual size of the volumetric data, denoted as [v.x, v.y, v.z]. In the local coordinate system of the volumetric space, the coordinate range of the volumetric data is from [0, 0, 0] to [v.x, v.y, v.z].</p><img src="`+w+'"><p>The origin of the visualization space is at the center of the volumetric data. The light sources are defined within the visualization space, including point lights, area lights, directional lights and panoramic HDR environment lights. All of these light sources are directed towards the origin of the visualization space and are used to illuminate the medical image volume data.</p><p>The transformation of the volume data from volume space to world space consists of the following steps: (1) translation by [-v.x/2, -v.y/2, -v.z/2]; (2) rotation (to ensure the center of rotation is at the center of the volume&#39;s bounding box); and (3) another translation.</p><p>Steps (1) and (2) are collectively referred to as the VolumeToVisSpace transformation, while the combined operations of (1), (2) and (3) are referred to as the VolumeToWorld transformation. In general, step (3) is not applied, allowing the light sources to always point towards the center of the volume data.</p><h4 id="light-coordinate-system" tabindex="-1"><a class="header-anchor" href="#light-coordinate-system"><span>Light Coordinate System</span></a></h4><p>All fundamental light sources (point lights, area lights and directional lights) are defined using spherical coordinates (latitude and longitude), with the direction always pointing towards the origin of the visualization space, which corresponds to the center of the volume data.</p><p>The representation of HDR panoramic environment light in the [panoramic coordinate system]:</p><img src="'+x+'"><p>The following figure illustrates the initial state of the HDR panoramic environment light in the visualization space:</p><img src="'+y+'"><p>In the visualization space, the panoramic environment light is typically rotated around the y-axis. The following figure shows the result after a 90-degree rotation:</p><img src="'+f+'"><p><strong>Mitsuba .vs. Crystal</strong></p><p>The camera coordinate system in Mitsuba differs from that used in Crystal. Specifically, they are both the right-handed, but the orientations of the x-axis and z-axis in Mitsuba are reversed compared to Crystal.</p><p><strong>PBRT .vs. Crystal</strong></p><p>In PBRT, the camera follows left-handed coordinate system. The screen space in PBRT keeps aspect of the output image. Namely, if w &gt; h, the width range of screen space in PBRT is <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mi>w</mi><mi mathvariant="normal">/</mi><mi>h</mi><mo separator="true">,</mo><mi>w</mi><mi mathvariant="normal">/</mi><mi>h</mi><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-w/h,w/h]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mord">/</span><span class="mord mathnormal">h</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mord">/</span><span class="mord mathnormal">h</span><span class="mclose">]</span></span></span></span>, the height range remain <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-1,1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>; if h &gt; w, the width range is <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-1,1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>, while the height range becomes <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mi>h</mi><mi mathvariant="normal">/</mi><mi>w</mi><mo separator="true">,</mo><mi>h</mi><mi mathvariant="normal">/</mi><mi>w</mi><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-h/w, h/w]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord mathnormal">h</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">h</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.02691em;">w</span><span class="mclose">]</span></span></span></span>.</p><h3 id="volume" tabindex="-1"><a class="header-anchor" href="#volume"><span>Volume</span></a></h3><h4 id="conventional-volume-data" tabindex="-1"><a class="header-anchor" href="#conventional-volume-data"><span>Conventional Volume Data</span></a></h4><p>The rotate way of the volume is as follows: first, rotate along <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> axis, and then rotate along <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">y</span></span></span></span> axis.</p><h4 id="volume-flip-and-permute" tabindex="-1"><a class="header-anchor" href="#volume-flip-and-permute"><span>Volume Flip and Permute</span></a></h4><p>The volumetric data may undergo flipping along the <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">y</span></span></span></span>, and <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>z</mi></mrow><annotation encoding="application/x-tex">z</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.04398em;">z</span></span></span></span> axes, respectively.</p><p>Additionally, it may be permuted across the <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span>-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>z</mi></mrow><annotation encoding="application/x-tex">z</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.04398em;">z</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">y</span></span></span></span>-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>z</mi></mrow><annotation encoding="application/x-tex">z</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.04398em;">z</span></span></span></span>, or <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span>-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">y</span></span></span></span> planes, which is analogous to a specific form of rotation. For example, a volume with the original resolution [A, B, C], when permuted along the <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span>-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">y</span></span></span></span> plane, will have its resolution transformed to [B, A, C].</p><h4 id="volume-loader" tabindex="-1"><a class="header-anchor" href="#volume-loader"><span>Volume-Loader</span></a></h4><p>In Crystal, each scene preset file includes a default volume file. Users can also drag new volume files or load data from buffers. The processing logic is as follows:</p><ul><li>If the newly loaded volume contains only Mask1, the resolution of Mask1 must match that of the original Intensity.</li><li>If the newly loaded volume contains both Intensity and Mask1, their resolutions must be identical.</li><li>If the newly loaded volume contains only Intensity and its resolution differs from that of the original volume, the memory resources will be reallocated. If the resolution remains unchanged, the existing memory resources will be reused.</li></ul><p>The default scene preset is used to initialize the [VolumeFile-Class] in the [MedicalVolumeDataPreset-Class]. And the check function [isValid-Func] in [MedicalVolumeDataPreset-Class] will initialize the [VolumeInfoPreset-Class] object using the [VolumeFile-Class] object. The volume data is initialized using [VolumeInfoPreset-Class].</p><p>When we load new volume file during rendering, the [.info] or [.dcm] will be used to update the [VolumeFile-Class] object. Then the [VolumeFile-Class] object is used to update the [VolumeInfoPreset-Class] object.</p><p>But the original volume may be fliped or permuted. The resolution of new volume must be compared after applying the same flip/permutation as the original volume.</p><p>In the [MedicalVolumeDataPreset-Class] (Preset), two sets of variables are maintained:</p><ul><li>resolution_load and voxelSpacing_load: store the original values before any permutation.</li><li>resolution_current and voxelSpacing_current: store the permuted values after transformation.</li></ul><p>In the [VolumeInfo-Class] (Scene), only the permuted state is retained:</p><ul><li>resolution: the permuted resolution.</li><li>voxelSpacing: the permuted voxel spacing.</li></ul><p>When a new volume is loaded, its resolution is first permuted. This permuted value is then compared directly with the resolution_current (the old permuted value) to determine subsequent processing steps.</p><h3 id="transfer-function" tabindex="-1"><a class="header-anchor" href="#transfer-function"><span>Transfer-Function</span></a></h3>',62))])}const C=o(v,[["render",k]]),L=JSON.parse('{"path":"/medical-vis/Development_Manual/Code_Structure.html","title":"Code Structure","lang":"en-US","frontmatter":{"title":"Code Structure","PageLayout":"custom","navbar":true,"aside":true,"description":"· · Module architecture Crystal module architecture with GUI, CLI and Python entry points, application and plugin boundaries, and the shared C++/CUDA engine. Figure 1. Execution...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Code Structure\\",\\"image\\":[\\"https://www.medical-vis.com/images/Development_Manual/current/module-architecture.svg\\",\\"https://www.medical-vis.com/images/Development_Manual/current/frame-lifecycle.svg\\",\\"https://www.medical-vis.com/images/Development_Manual/current/plugin-lifecycle.svg\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://www.medical-vis.com/medical-vis/Development_Manual/Code_Structure.html"}],["meta",{"property":"og:site_name","content":"Crystal"}],["meta",{"property":"og:title","content":"Code Structure"}],["meta",{"property":"og:description","content":"· · Module architecture Crystal module architecture with GUI, CLI and Python entry points, application and plugin boundaries, and the shared C++/CUDA engine. Figure 1. Execution..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://www.medical-vis.com/images/Development_Manual/current/module-architecture.svg"}],["meta",{"property":"og:locale","content":"en-US"}]]},"git":{"createdTime":1760370562000},"autoDesc":true,"filePathRelative":"medical-vis/Development_Manual/Code_Structure.md","headers":[]}');export{C as comp,L as data};
